curl -X POST "https://api.supermemory.ai/ns/user_123/document" \
  -H "Authorization: Bearer $SUPERMEMORY_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "content": "Sarah is being promoted to VP of Product.",
    "dreaming": "instant",
    "id": "chat_session_1",
    "metadata": { "type": "conversation" }
  }'

curl -X POST "https://api.supermemory.ai/ns/user_123/document/batch" \
  -H "Authorization: Bearer $SUPERMEMORY_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "documents": [
      { "content": "Q3 roadmap notes", "id": "doc_roadmap" },
      { "content": "Gift policy for VP promotions", "id": "doc_gifts" }
    ],
    "dreaming": "instant"
  }'

curl -X PATCH "https://api.supermemory.ai/ns/user_123/document/chat_session_1" \
  -H "Authorization: Bearer $SUPERMEMORY_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "content": "Updated notes — Sarah is now VP of Product.",
    "metadata": { "type": "conversation" }
  }'

curl -X POST "https://api.supermemory.ai/ns/user_123/search" \
  -H "Authorization: Bearer $SUPERMEMORY_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "query": "gift ideas for a VP promotion after a Tokyo offsite",
    "searchMode": "hybrid",
    "limit": 5,
    "include": { "related": true },
    "filter": {
      "operator": "and",
      "operands": [
        { "field": "category", "operator": "eq", "value": "work" },
        { "field": "importance", "operator": "gte", "value": 0.8 }
      ]
    }
  }'

import Supermemory from "supermemory";

const client = new Supermemory({
  apiKey: process.env.SUPERMEMORY_API_KEY,
});

const res = await fetch("https://api.supermemory.ai/ns/user_123/profile/buckets", {
  headers: {
    Authorization: `Bearer ${process.env.SUPERMEMORY_API_KEY}`,
  },
});
const data = await res.json();
console.log(data);
